type Event = { turnId: string; kind: string; [key: string]: unknown };
type Tool = { id: string; title: string; status: "pending" | "running" | "completed" | "failed"; output: string };
type Turn = { text: string; tools: Tool[]; stopReason: string | null };

export function assembleTurn(turnId: string, events: Event[]): Turn {
  let text = "";
  let stopReason: string | null = null;
  const tools = new Map<string, Tool>();

  for (const event of events) {
    if (event.turnId !== turnId) continue;

    if (event.kind === "message") {
      const value = typeof event.text === "string" ? event.text : "";
      if (event.mode === "replace") text = value;
      else text += value;
    } else if (event.kind === "tool") {
      const id = event.id as string;
      let tool = tools.get(id);
      if (tool === undefined) {
        tool = { id, title: "", status: "pending", output: "" };
        tools.set(id, tool);
      }
      if (typeof event.title === "string") tool.title = event.title;
      if (typeof event.status === "string") tool.status = event.status as Tool["status"];
      if (event.output === null) tool.output = "";
      else if (typeof event.output === "string") {
        if (event.outputMode === "replace") tool.output = event.output;
        else tool.output += event.output;
      }
    } else if (event.kind === "done") {
      stopReason = event.stopReason as string;
      break;
    }
  }

  return {
    text,
    tools: Array.from(tools.values(), (t) => ({ id: t.id, title: t.title, status: t.status, output: t.output })),
    stopReason,
  };
}
